// ClipStack — a menu bar clipboard history for macOS.
import AppKit
import Carbon.HIToolbox
import ServiceManagement

// MARK: - Settings

let maxItems = 200
let pollInterval: TimeInterval = 0.5
let hotKeyCode = UInt32(kVK_ANSI_V)
let hotKeyModifiers = UInt32(cmdKey | shiftKey) // ⌘⇧V
let menuPreviewCount = 10

// Password managers mark secrets with these types (nspasteboard.org convention); never record them.
let skippedTypes: Set<String> = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
]

// MARK: - History store

final class Store {
    private(set) var items: [String] = []
    private let url: URL

    init() {
        let dir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("ClipStack", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        url = dir.appendingPathComponent("history.json")
        guard let data = try? Data(contentsOf: url) else { return }
        do {
            items = try JSONDecoder().decode([String].self, from: data)
        } catch {
            // Keep the unreadable file for inspection instead of silently overwriting it.
            NSLog("ClipStack: history unreadable, moved aside: \(error)")
            try? FileManager.default.moveItem(at: url, to: url.appendingPathExtension("corrupt"))
        }
    }

    func add(_ text: String) {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        items.removeAll { $0 == text }
        items.insert(text, at: 0)
        if items.count > maxItems { items.removeLast(items.count - maxItems) }
        save()
    }

    func clear() {
        items.removeAll()
        save()
    }

    private func save() {
        do {
            try JSONEncoder().encode(items).write(to: url, options: .atomic)
            // History can hold sensitive text; keep it readable by this user only.
            try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: url.path)
        } catch {
            NSLog("ClipStack: failed to save history: \(error)")
        }
    }
}

// MARK: - Clipboard watcher

// macOS posts no clipboard-change notification, so poll the change counter (cheap).
final class Watcher {
    private var lastCount = NSPasteboard.general.changeCount
    private var timer: Timer?
    private let onCopy: (String) -> Void

    init(onCopy: @escaping (String) -> Void) { self.onCopy = onCopy }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: pollInterval, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    private func tick() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastCount else { return }
        lastCount = pb.changeCount
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: skippedTypes), let text = pb.string(forType: .string) else { return }
        onCopy(text)
    }
}

// MARK: - Global hotkey

final class HotKey {
    private var ref: EventHotKeyRef?
    private let action: () -> Void
    private(set) var status: OSStatus = noErr

    init(keyCode: UInt32, modifiers: UInt32, action: @escaping () -> Void) {
        self.action = action
        var spec = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
        InstallEventHandler(GetApplicationEventTarget(), { _, _, userData in
            Unmanaged<HotKey>.fromOpaque(userData!).takeUnretainedValue().action()
            return noErr
        }, 1, &spec, Unmanaged.passUnretained(self).toOpaque(), nil)
        let id = EventHotKeyID(signature: OSType(0x434C_5053), id: 1) // 'CLPS'
        status = RegisterEventHotKey(keyCode, modifiers, id, GetApplicationEventTarget(), 0, &ref)
    }
}

// MARK: - Paste

func paste(_ text: String) {
    let pb = NSPasteboard.general
    pb.clearContents()
    pb.setString(text, forType: .string)
    guard AXIsProcessTrusted() else {
        promptAccessibility()
        return
    }
    // Give the target app a moment to regain focus before sending ⌘V.
    DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
        let src = CGEventSource(stateID: .combinedSessionState)
        for down in [true, false] {
            let e = CGEvent(keyboardEventSource: src, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: down)
            e?.flags = .maskCommand
            e?.post(tap: .cghidEventTap)
        }
    }
}

func promptAccessibility() {
    AXIsProcessTrustedWithOptions(["AXTrustedCheckOptionPrompt": true] as CFDictionary)
}

func preview(_ text: String) -> String {
    let flat = text.split(whereSeparator: \.isWhitespace).joined(separator: " ")
    return flat.count > 80 ? String(flat.prefix(80)) + "…" : flat
}

func alert(_ title: String, _ message: String) {
    NSApp.activate(ignoringOtherApps: true)
    let a = NSAlert()
    a.messageText = title
    a.informativeText = message
    a.runModal()
}

// MARK: - Picker panel (⌘⇧V)

final class KeyPanel: NSPanel {
    override var canBecomeKey: Bool { true }
}

final class Picker: NSObject, NSTableViewDataSource, NSTableViewDelegate, NSSearchFieldDelegate, NSWindowDelegate {
    private let panel: KeyPanel
    private let search = NSSearchField()
    private let table = NSTableView()
    private let store: Store
    private var filtered: [String] = []
    private var previousApp: NSRunningApplication?

    init(store: Store) {
        self.store = store
        let size = NSSize(width: 460, height: 380)
        panel = KeyPanel(contentRect: NSRect(origin: .zero, size: size),
                         styleMask: [.titled, .fullSizeContentView], backing: .buffered, defer: false)
        super.init()

        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true
        panel.isMovableByWindowBackground = true
        panel.level = .floating
        panel.hidesOnDeactivate = false
        panel.delegate = self
        [.closeButton, .miniaturizeButton, .zoomButton].forEach { panel.standardWindowButton($0)?.isHidden = true }

        let bg = NSVisualEffectView(frame: NSRect(origin: .zero, size: size))
        bg.material = .popover
        bg.state = .active
        panel.contentView = bg

        search.frame = NSRect(x: 12, y: size.height - 44, width: size.width - 24, height: 28)
        search.placeholderString = "Search clipboard history"
        search.delegate = self
        bg.addSubview(search)

        let column = NSTableColumn(identifier: .init("text"))
        column.width = size.width - 24
        table.addTableColumn(column)
        table.headerView = nil
        table.rowHeight = 24
        table.dataSource = self
        table.delegate = self
        table.target = self
        table.doubleAction = #selector(pickSelected)

        let scroll = NSScrollView(frame: NSRect(x: 12, y: 12, width: size.width - 24, height: size.height - 64))
        scroll.documentView = table
        scroll.hasVerticalScroller = true
        scroll.drawsBackground = false
        table.backgroundColor = .clear
        bg.addSubview(scroll)
    }

    func toggle() {
        panel.isVisible ? dismiss(restoreFocus: true) : show()
    }

    private func show() {
        previousApp = NSWorkspace.shared.frontmostApplication
        search.stringValue = ""
        refilter()

        // Open near the mouse, kept fully on screen.
        let mouse = NSEvent.mouseLocation
        let screen = NSScreen.screens.first { $0.frame.contains(mouse) } ?? NSScreen.main!
        let vis = screen.visibleFrame
        let size = panel.frame.size
        let x = min(max(mouse.x - size.width / 2, vis.minX), vis.maxX - size.width)
        let y = min(max(mouse.y - size.height, vis.minY), vis.maxY - size.height)
        panel.setFrameOrigin(NSPoint(x: x, y: y))

        NSApp.activate(ignoringOtherApps: true)
        panel.makeKeyAndOrderFront(nil)
        panel.makeFirstResponder(search)
    }

    private func dismiss(restoreFocus: Bool) {
        panel.orderOut(nil)
        if restoreFocus { previousApp?.activate() }
    }

    @objc private func pickSelected() {
        let row = table.selectedRow
        guard filtered.indices.contains(row) else { return }
        let text = filtered[row]
        dismiss(restoreFocus: true)
        paste(text)
    }

    private func refilter() {
        let q = search.stringValue
        filtered = q.isEmpty ? store.items : store.items.filter { $0.localizedCaseInsensitiveContains(q) }
        table.reloadData()
        if !filtered.isEmpty { table.selectRowIndexes([0], byExtendingSelection: false) }
        table.scrollRowToVisible(0)
    }

    private func moveSelection(_ delta: Int) {
        guard !filtered.isEmpty else { return }
        let row = min(max(table.selectedRow + delta, 0), filtered.count - 1)
        table.selectRowIndexes([row], byExtendingSelection: false)
        table.scrollRowToVisible(row)
    }

    // Search field keys drive the list: ↑/↓ move, Enter pastes, Esc closes.
    func controlTextDidChange(_ obj: Notification) { refilter() }

    func control(_ control: NSControl, textView: NSTextView, doCommandBy sel: Selector) -> Bool {
        switch sel {
        case #selector(NSResponder.moveUp(_:)): moveSelection(-1)
        case #selector(NSResponder.moveDown(_:)): moveSelection(1)
        case #selector(NSResponder.insertNewline(_:)): pickSelected()
        case #selector(NSResponder.cancelOperation(_:)): dismiss(restoreFocus: true)
        default: return false
        }
        return true
    }

    func windowDidResignKey(_ notification: Notification) {
        if panel.isVisible { dismiss(restoreFocus: false) }
    }

    func numberOfRows(in tableView: NSTableView) -> Int { filtered.count }

    func tableView(_ tableView: NSTableView, viewFor tableColumn: NSTableColumn?, row: Int) -> NSView? {
        let id = NSUserInterfaceItemIdentifier("cell")
        let label = (tableView.makeView(withIdentifier: id, owner: nil) as? NSTextField) ?? {
            let f = NSTextField(labelWithString: "")
            f.identifier = id
            f.lineBreakMode = .byTruncatingTail
            return f
        }()
        label.stringValue = preview(filtered[row])
        return label
    }
}

// MARK: - App

final class AppDelegate: NSObject, NSApplicationDelegate, NSMenuDelegate {
    private let store = Store()
    private var watcher: Watcher!
    private var picker: Picker!
    private var hotKey: HotKey!
    private var statusItem: NSStatusItem!

    func applicationDidFinishLaunching(_ notification: Notification) {
        statusItem = NSStatusBar.system.statusItem(withLength: NSStatusItem.squareLength)
        statusItem.button?.image = NSImage(systemSymbolName: "doc.on.clipboard", accessibilityDescription: "ClipStack")
        let menu = NSMenu()
        menu.delegate = self
        statusItem.menu = menu

        picker = Picker(store: store)
        watcher = Watcher { [store] in store.add($0) }
        watcher.start()

        hotKey = HotKey(keyCode: hotKeyCode, modifiers: hotKeyModifiers) { [weak self] in self?.picker.toggle() }
        if hotKey.status != noErr {
            alert("Hotkey ⌘⇧V unavailable",
                  "Another app already uses it (error \(hotKey.status)). Use the menu bar icon, or change hotKeyCode in main.swift.")
        }

        if !AXIsProcessTrusted() { promptAccessibility() }
    }

    // Rebuilt on every open so it always shows the latest history.
    func menuNeedsUpdate(_ menu: NSMenu) {
        menu.removeAllItems()
        if store.items.isEmpty {
            menu.addItem(withTitle: "No history yet", action: nil, keyEquivalent: "").isEnabled = false
        }
        for (i, text) in store.items.prefix(menuPreviewCount).enumerated() {
            let item = NSMenuItem(title: preview(text), action: #selector(pasteFromMenu(_:)), keyEquivalent: "")
            item.tag = i
            item.target = self
            menu.addItem(item)
        }
        menu.addItem(.separator())
        add(menu, "Show All History (⌘⇧V)", #selector(showPicker))
        add(menu, "Clear History", #selector(clearHistory))
        add(menu, "Launch at Login", #selector(toggleLogin)).state =
            SMAppService.mainApp.status == .enabled ? .on : .off
        menu.addItem(.separator())
        add(menu, "Quit ClipStack", #selector(NSApplication.terminate(_:)), target: NSApp)
    }

    @discardableResult
    private func add(_ menu: NSMenu, _ title: String, _ action: Selector, target: AnyObject? = nil) -> NSMenuItem {
        let item = menu.addItem(withTitle: title, action: action, keyEquivalent: "")
        item.target = target ?? self
        return item
    }

    @objc private func pasteFromMenu(_ sender: NSMenuItem) {
        guard store.items.indices.contains(sender.tag) else { return }
        paste(store.items[sender.tag])
    }

    @objc private func showPicker() { picker.toggle() }

    @objc private func clearHistory() { store.clear() }

    @objc private func toggleLogin() {
        let service = SMAppService.mainApp
        do {
            if service.status == .enabled {
                try service.unregister()
            } else {
                try service.register()
                if service.status == .requiresApproval {
                    alert("Approve ClipStack", "Turn ClipStack on in System Settings → General → Login Items.")
                    SMAppService.openSystemSettingsLoginItems()
                }
            }
        } catch {
            alert("Launch at Login failed", error.localizedDescription)
        }
    }
}

let app = NSApplication.shared
let delegate = AppDelegate()
app.delegate = delegate
app.setActivationPolicy(.accessory)
app.run()
